function validate([graph]) {
  const n = graph.length;
  if (n < 1 || n > 12) return 'graph needs 1 to 12 nodes.';
  const has = Array.from({ length: n }, () => new Set());
  for (let i = 0; i < n; i++) {
    for (const v of graph[i]) {
      if (!Number.isInteger(v) || v < 0 || v >= n) return 'Every neighbour must be a node label from 0 to n - 1.';
      if (v === i) return 'A node cannot list itself.';
      if (has[i].has(v)) return 'A neighbour appears twice in one list.';
      has[i].add(v);
    }
  }
  for (let i = 0; i < n; i++) for (const v of graph[i]) if (!has[v].has(i)) return 'Edges must be listed in both directions.';
  const seen = new Set([0]);
  const queue = [0];
  for (let k = 0; k < queue.length; k++) for (const v of graph[queue[k]]) if (!seen.has(v)) { seen.add(v); queue.push(v); }
  if (seen.size !== n) return 'The graph must be connected.';
  return null;
}

