function shortestPathLength(graph) {
  const n = graph.length;
  // Floyd-Warshall distances, then the cheapest order of first visits by DP over (visited set, last node).
  const dist = Array.from({ length: n }, (_, a) => Array.from({ length: n }, (_, b) => (a === b ? 0 : graph[a].includes(b) ? 1 : Infinity)));
  for (let k = 0; k < n; k++) for (let a = 0; a < n; a++) for (let b = 0; b < n; b++) dist[a][b] = Math.min(dist[a][b], dist[a][k] + dist[k][b]);
  const cost = Array.from({ length: 1 << n }, () => new Array(n).fill(Infinity));
  for (let v = 0; v < n; v++) cost[1 << v][v] = 0;
  for (let set = 1; set < 1 << n; set++) {
    for (let last = 0; last < n; last++) {
      if (cost[set][last] === Infinity) continue;
      for (let v = 0; v < n; v++) if (!(set & (1 << v))) cost[set | (1 << v)][v] = Math.min(cost[set | (1 << v)][v], cost[set][last] + dist[last][v]);
    }
  }
  return Math.min(...cost[(1 << n) - 1]);
}

