function generate(rand, size) {
  const n = size === 'large' ? 12 : 1 + Math.floor(rand() * 7);
  const labels = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [labels[i], labels[j]] = [labels[j], labels[i]]; }
  const edges = new Set();
  const add = (a, b) => { if (a !== b) edges.add(Math.min(a, b) * 16 + Math.max(a, b)); };
  // A random spanning tree keeps the graph connected; extra edges vary its density.
  const shape = rand();
  for (let i = 1; i < n; i++) {
    const parent = shape < 0.25 ? i - 1 : shape < 0.4 ? 0 : Math.floor(rand() * i);
    add(labels[i], labels[parent]);
  }
  const density = rand() < 0.4 ? 0 : rand() * 0.6;
  for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) if (rand() < density) add(a, b);
  const graph = Array.from({ length: n }, () => []);
  for (const e of edges) { const a = Math.floor(e / 16), b = e % 16; graph[a].push(b); graph[b].push(a); }
  for (const list of graph) for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
  return [graph];
}
